//! Independent exact-input direct-DFT fixtures; test-only, no production change.
//! Generated by numerical-qualification/stage2/cross_spectral_reference.py.
use super::*;
use crate::{
    Album, Analyzer, BitDepth, Format, Measurement as M, Measurements, NoiseSnapshot, Outcome,
    Settings, Track, Value,
};

struct Fixture {
    name: String,
    rate: u32,
    n: usize,
    pcm: Vec<f64>,
    // One-sided raw power (per-channel mean), mid/side and cross-power.
    bins: Vec<[f64; 5]>,
    band: [f64; 2],
    total: [f64; 2],
    energy: f64,
    delay: Option<f64>,
    bass: f64,
    tol: f64,
    delay_tol: f64,
}

fn fixtures() -> Vec<Fixture> {
    let mut result = Vec::new();
    let mut current: Option<Fixture> = None;
    for line in include_str!("../tests/fixtures/cross_spectral_reference.tsv").lines() {
        let row: Vec<_> = line.split('\t').collect();
        match row[0] {
            x if x.starts_with('#') => (),
            "CASE" => {
                assert!(current.is_none());
                let frames = row[3].parse::<usize>().unwrap();
                current = Some(Fixture {
                    name: row[1].to_string(),
                    rate: row[2].parse().unwrap(),
                    n: row[4].parse().unwrap(),
                    pcm: vec![0.0; frames * 2],
                    bins: Vec::new(),
                    band: [0.0; 2],
                    total: [0.0; 2],
                    energy: 0.0,
                    delay: None,
                    bass: 0.0,
                    tol: 0.0,
                    delay_tol: 0.0,
                });
            }
            "S" => {
                let f = current.as_mut().unwrap();
                let i = row[1].parse::<usize>().unwrap();
                for ch in 0..2 {
                    f.pcm[i * 2 + ch] =
                        f64::from(row[ch + 2].parse::<i32>().unwrap()) / 2147483648.0;
                }
            }
            "B" => {
                let f = current.as_mut().unwrap();
                assert_eq!(row[1].parse::<usize>().unwrap(), f.bins.len());
                f.bins
                    .push(std::array::from_fn(|i| row[i + 2].parse().unwrap()));
            }
            "T" => {
                let mut f = current.take().unwrap();
                f.band = [row[1].parse().unwrap(), row[2].parse().unwrap()];
                f.total = [row[3].parse().unwrap(), row[4].parse().unwrap()];
                f.energy = row[5].parse().unwrap();
                f.delay = if row[6] == "none" {
                    None
                } else {
                    Some(row[6].parse().unwrap())
                };
                f.bass = row[7].parse().unwrap();
                f.tol = row[8].parse().unwrap();
                f.delay_tol = row[9].parse().unwrap();
                assert_eq!(f.bins.len(), f.n / 2 + 1);
                assert!(f.energy > 0.0 && f.tol > 0.0 && f.tol < 1e-8);
                result.push(f);
            }
            _ => panic!("invalid fixture row: {line}"),
        }
    }
    assert!(current.is_none());
    assert_eq!(result.len(), 6);
    result
}

fn l1(actual: &[f64], expected: impl Iterator<Item = f64>, scale: f64, f: &Fixture, label: &str) {
    let expected: Vec<_> = expected.collect();
    assert_eq!(actual.len(), expected.len());
    assert!(scale > 0.0);
    let err = actual
        .iter()
        .zip(expected)
        .map(|(a, b)| (a - b).abs())
        .sum::<f64>()
        / scale;
    assert!(
        err <= f.tol,
        "{} {label}: scaled L1 error {err:e}, tolerance {:e}",
        f.name,
        f.tol
    );
}

fn close(actual: f64, expected: f64, tol: f64, label: &str) {
    assert!(
        (actual - expected).abs() <= tol,
        "{label}: {actual:.17e} versus {expected:.17e}; tol {tol:e}"
    );
}

fn assert_delay(actual: Option<f64>, f: &Fixture) {
    match (actual, f.delay) {
        (Some(a), Some(b)) => close(a, b, f.delay_tol, &f.name),
        (None, None) => (),
        _ => panic!("{}: expected delay {:?}, got {actual:?}", f.name, f.delay),
    }
}

fn assert_bass(actual: BassWidth, f: &Fixture) {
    assert_eq!(
        actual,
        if f.bass == 0.0 {
            BassWidth::Full
        } else {
            BassWidth::MonoBelow(f.bass)
        },
        "{}",
        f.name
    );
}

#[test]
fn direct_dft_reference_checks_all_spectral_bins_and_stereo_classifications() {
    for f in fixtures() {
        // Same actual engine and FFT as production; compare independently
        // constructed reference bins, not a second RustFFT invocation.
        let mut prior: Option<SpectralEngine> = None;
        for chunk in [1, 257, 4093] {
            let mut engine = SpectralEngine::new(f.rate, 2, true, true, true, false, false, false);
            for pcm in f.pcm.chunks(chunk * 2) {
                engine.push(pcm);
            }
            engine.flush();
            assert_eq!(engine.spectrum.frames as usize, f.pcm.len() / 2);
            l1(
                &engine.spectrum.sums,
                f.bins.iter().map(|x| x[0]),
                f.energy,
                &f,
                "power",
            );
            let (mid, side) = engine.bass.as_ref().unwrap();
            l1(
                mid,
                f.bins.iter().map(|x| x[1]),
                f.bins.iter().map(|x| x[1]).sum(),
                &f,
                "mid",
            );
            l1(
                side,
                f.bins.iter().map(|x| x[2]),
                f.bins.iter().map(|x| x[2]).sum(),
                &f,
                "side",
            );
            let (cross, le, re) = engine.delay.as_ref().unwrap();
            assert_eq!(cross.len(), f.bins.len());
            // Complex L1 relative to cross operand norm; do not divide by a
            // cancelling residual (cross_cancel has mathematically zero C).
            let norm = f.band[0].sqrt() * f.band[1].sqrt();
            let error = cross
                .iter()
                .zip(&f.bins)
                .map(|(a, b)| (a.re - b[3]).hypot(a.im - b[4]))
                .sum::<f64>()
                / norm;
            assert!(
                error <= f.tol,
                "{}: normalized cross error {error:e}",
                f.name
            );
            for (a, b) in [
                (*le, f.band[0]),
                (*re, f.band[1]),
                (engine.delay_total[0], f.total[0]),
                (engine.delay_total[1], f.total[1]),
            ] {
                close(a, b, f.tol * b, &f.name);
            }
            close(
                engine.spectrum.sums.iter().sum(),
                f.energy,
                f.tol * f.energy,
                &f.name,
            );
            assert_bass(engine.bass_width(), &f);
            assert_delay(engine.delay_us(), &f);
            if let Some(old) = &prior {
                assert_eq!(
                    old.spectrum.sums, engine.spectrum.sums,
                    "{} power chunking",
                    f.name
                );
                assert_eq!(old.bass, engine.bass, "{} bass chunking", f.name);
                assert_eq!(old.delay, engine.delay, "{} cross chunking", f.name);
                assert_eq!(old.delay_total, engine.delay_total);
            }
            prior = Some(engine);
        }
    }
}

const NOISE: [M; 6] = [
    M::NoiseFloor,
    M::EffectiveBits,
    M::DynamicRange,
    M::NoiseSpectrum,
    M::NoiseByBand,
    M::HumAndIdleTones,
];
fn selection() -> Measurements {
    let mut ms = NOISE.to_vec();
    ms.extend([
        M::AverageSpectrum,
        M::InterChannelDelay,
        M::BassWidth,
        M::BitsInUse,
    ]);
    Measurements::new(&ms)
}

fn track(f: &Fixture, pcm: &[f64], chunk: usize) -> Track {
    let mut a = Analyzer::new(
        Format {
            sample_rate: f.rate,
            channels: 2,
            encoding: Encoding::Integer(32),
            loudness_roles: None,
        },
        selection(),
        Settings {
            shortest_gap_seconds: 0.05,
            ..Settings::default()
        },
    )
    .unwrap();
    for p in pcm.chunks(chunk * 2) {
        a.push_interleaved(p).unwrap();
    }
    a.finish().unwrap()
}
fn scalar(out: Outcome<Value>) -> f64 {
    match out {
        Outcome::Value(Value::Scalar(x)) => x,
        other => panic!("expected scalar; got {other:?}"),
    }
}
fn full() -> NoiseView {
    NoiseView {
        band: Band::Full,
        weighting: Weighting::Unweighted,
    }
}

#[test]
fn direct_dft_reference_survives_public_selection_and_noise_record_restore() {
    let cases = fixtures();
    for f in &cases {
        let t = track(f, &f.pcm, 113);
        match t.measure(M::InterChannelDelay, full()) {
            Outcome::Value(Value::Scalar(x)) => assert_delay(Some(x), f),
            Outcome::CantTell(_) => assert_delay(None, f),
            other => panic!("unexpected delay: {other:?}"),
        }
        match t.measure(M::BassWidth, full()) {
            Outcome::Value(Value::BassWidth(x)) => assert_bass(x, f),
            other => panic!("unexpected bass: {other:?}"),
        }
        // Only this fixture is intentionally wholly quiet. Other sparse
        // programme fixtures can have independent qualifying quiet gaps.
        if f.name == "quiet_partial" {
            let record = t.noise_record();
            let q = record
                .quiet
                .as_ref()
                .expect("low-level partial passage qualifies");
            assert_eq!(q.frames, t.frames());
            assert_eq!(q.fft_size, f.n);
            l1(
                &q.bin_power_sums,
                f.bins.iter().map(|x| x[0]),
                f.energy,
                f,
                "retained quiet power",
            );
            let rms_db = 10.0 * (f.energy / t.frames() as f64).log10();
            close(
                scalar(t.measure(M::NoiseFloor, full())),
                rms_db,
                10.0 * f.tol / (1.0 - f.tol) / std::f64::consts::LN_10 + 1e-12,
                "full-band RMS",
            );
            assert!(matches!(
                t.measure(M::BitsInUse, full()),
                Outcome::Value(Value::Bits(BitDepth::Integer {
                    declared: Some(32),
                    grid_step: 1,
                    grid_scale_bits: 31,
                    used: 32,
                    ..
                }))
            ));
            let expected_bits = -rms_db / (20.0 * 2.0_f64.log10());
            match t.measure(M::EffectiveBits, full()) {
                Outcome::Value(Value::ApproximateBits(x)) => {
                    close(x, expected_bits, 1e-11, "effective resolution")
                }
                other => panic!("unexpected resolution: {other:?}"),
            }
            let restored = NoiseSnapshot::from_record(record).unwrap();
            for m in NOISE {
                for band in [Band::Full, Band::Audible, Band::ToNyquist] {
                    for weighting in [Weighting::Unweighted, Weighting::A, Weighting::ItuR468] {
                        let view = NoiseView { band, weighting };
                        assert_eq!(
                            t.measure(m, view),
                            restored.measure(m, view),
                            "restored {m:?} {view:?}"
                        );
                    }
                }
            }
        }
    }
    // Use a second entirely quiet, exact-grid track at a different clock.
    // A power-of-two gain preserves exact PCM codes in delay_right.
    let a = cases.iter().find(|f| f.name == "quiet_partial").unwrap();
    let b = cases.iter().find(|f| f.name == "delay_right").unwrap();
    let gain = 2.0_f64.powi(-16);
    let quiet: Vec<_> = b.pcm.iter().map(|x| x * gain).collect();
    let ta = track(a, &a.pcm, 127);
    let tb = track(b, &quiet, 701);
    assert_eq!(
        ta.noise_record().quiet.as_ref().unwrap().frames,
        ta.frames()
    );
    assert_eq!(
        tb.noise_record().quiet.as_ref().unwrap().frames,
        tb.frames()
    );
    let duration = ta.duration_seconds() + tb.duration_seconds();
    let power =
        (a.energy / f64::from(a.rate) + b.energy * gain * gain / f64::from(b.rate)) / duration;
    let restored = [
        NoiseSnapshot::from_record(ta.noise_record()).unwrap(),
        NoiseSnapshot::from_record(tb.noise_record()).unwrap(),
    ];
    let album = Album::from_tracks(vec![ta, tb]).unwrap();
    close(
        scalar(album.measure(M::NoiseFloor, full())),
        10.0 * power.log10(),
        2e-12,
        "mixed-clock pooled RMS",
    );
    for m in NOISE {
        for band in [Band::Full, Band::Audible, Band::ToNyquist] {
            for weighting in [Weighting::Unweighted, Weighting::A, Weighting::ItuR468] {
                let view = NoiseView { band, weighting };
                assert_eq!(
                    album.measure(m, view),
                    NoiseSnapshot::measure_album(&restored, m, view).unwrap()
                );
            }
        }
    }
}
